t.script:
(function(){
  var pop=document.getElementById('ha-pop'), curCell=null, curEmp=0;
  function toDec(v){ if(!v){ return 0; } var p=v.split(':'); return parseInt(p[0]) + parseInt(p[1]||0)/60; }
  function rpcSave(emp, date, typ, md, mf, ad, af, done){
    fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[2012]],kwargs:{context:{active_model:'x_heures_jour',hj_emp:emp,hj_date:date,hj_type:typ,hj_m_deb:md,hj_m_fin:mf,hj_am_deb:ad,hj_am_fin:af}}}})
    }).then(function(r){return r.json();}).then(function(d){
      if(d.error){ alert('Échec : '+(d.error.data && d.error.data.message || d.error.message)); return; }
      done(d.result||{});
    }).catch(function(){ alert('Échec réseau'); });
  }
  document.addEventListener('click', function(e){
    var cell = e.target.closest('.ha-cell');
    if(cell){
      curCell = cell; curEmp = parseInt(cell.closest('tr').getAttribute('data-emp'));
      document.getElementById('ha-pop-t').textContent = cell.closest('tr').getAttribute('data-name') + ' — ' + cell.getAttribute('data-date');
      document.getElementById('ha-md').value = cell.getAttribute('data-md') || cell.getAttribute('data-tmd');
      document.getElementById('ha-mf').value = cell.getAttribute('data-mf') || cell.getAttribute('data-tmf');
      document.getElementById('ha-ad').value = cell.getAttribute('data-ad') || cell.getAttribute('data-tad');
      document.getElementById('ha-af').value = cell.getAttribute('data-af') || cell.getAttribute('data-taf');
      pop.style.display='flex';
      return;
    }
    var q = e.target.closest('.ha-quick');
    if(q){
      var tr = q.closest('tr');
      var cells = tr.querySelectorAll('.ha-cell');
      var todo = [];
      cells.forEach(function(c){
        if(!c.getAttribute('data-type') && parseFloat(c.getAttribute('data-theo')||0) > 0){ todo.push(c); }
      });
      if(!todo.length){ return; }
      if(!confirm(tr.getAttribute('data-name') + ' : remplir ' + todo.length + ' jour(s) avec l’horaire habituel ?')){ return; }
      var emp = parseInt(tr.getAttribute('data-emp'));
      var left = todo.length;
      todo.forEach(function(c){
        rpcSave(emp, c.getAttribute('data-date'), 'travail', toDec(c.getAttribute('data-tmd')), toDec(c.getAttribute('data-tmf')), toDec(c.getAttribute('data-tad')), toDec(c.getAttribute('data-taf')), function(){
          left -= 1; if(left === 0){ location.reload(); }
        });
      });
    }
  });
  document.getElementById('ha-pop-x').addEventListener('click', function(){ pop.style.display='none'; });
  pop.querySelectorAll('.ha-bt[data-t]').forEach(function(b){
    b.addEventListener('click', function(){
      var t = b.getAttribute('data-t');
      if(t === 'normal'){
        rpcSave(curEmp, curCell.getAttribute('data-date'), 'travail', toDec(curCell.getAttribute('data-tmd')), toDec(curCell.getAttribute('data-tmf')), toDec(curCell.getAttribute('data-tad')), toDec(curCell.getAttribute('data-taf')), function(){ location.reload(); });
      } else {
        rpcSave(curEmp, curCell.getAttribute('data-date'), t, 0, 0, 0, 0, function(){ location.reload(); });
      }
    });
  });
  document.getElementById('ha-save').addEventListener('click', function(){
    rpcSave(curEmp, curCell.getAttribute('data-date'), 'travail',
      toDec(document.getElementById('ha-md').value), toDec(document.getElementById('ha-mf').value),
      toDec(document.getElementById('ha-ad').value), toDec(document.getElementById('ha-af').value),
      function(){ location.reload(); });
  });
})();
